import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { test } from 'node:test';
import { decodeReadonlyModelPreflightResponse, PREFLIGHT_HTTP_LIMITS, type PreflightHttpResponse } from '../src/policy/readonly-model-preflight-protocol.js';

const jsonProfile = 'responses-candidate-json-v1';
const sseProfile = 'responses-candidate-sse-v1';
const finalText = '{"answer":"가나다"}';
// Independently authored candidate fixtures, never generated by the production encoder/decoder.
const item = (text = finalText) => ({ id: 'msg_golden', type: 'message', role: 'assistant', status: 'completed', content: [{ type: 'output_text', text, annotations: [] }] });
const completed = (text = finalText) => ({ id: 'resp_golden', object: 'response', status: 'completed', model: 'synthetic-investigator-v1', output: [item(text)] });
const events = (text = finalText): Record<string, unknown>[] => [
  { type: 'response.created', sequence_number: 0, response: { id: 'resp_golden', object: 'response', status: 'in_progress', model: 'synthetic-investigator-v1', output: [] } },
  { type: 'response.output_item.added', sequence_number: 1, response_id: 'resp_golden', output_index: 0, item: { id: 'msg_golden', type: 'message', role: 'assistant', status: 'in_progress', content: [] } },
  { type: 'response.output_text.delta', sequence_number: 2, response_id: 'resp_golden', item_id: 'msg_golden', output_index: 0, content_index: 0, delta: text },
  { type: 'response.output_text.done', sequence_number: 3, response_id: 'resp_golden', item_id: 'msg_golden', output_index: 0, content_index: 0, text },
  { type: 'response.output_item.done', sequence_number: 4, response_id: 'resp_golden', output_index: 0, item: item(text) },
  { type: 'response.completed', sequence_number: 5, response: completed(text) },
];
const sse = (values = events()): string => values.map((event) => `event: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`).join('');
const response = (raw: string | Uint8Array, stream = false, chunkSize = 97): PreflightHttpResponse => {
  const bytes = typeof raw === 'string' ? Buffer.from(raw) : raw;
  return { status: 200, headers: [['Content-Type', stream ? 'text/event-stream' : 'application/json']],
    body: { async *[Symbol.asyncIterator]() { for (let offset = 0; offset < bytes.length; offset += chunkSize) yield bytes.subarray(offset, offset + chunkSize); } } };
};
const decode = (raw: string | Uint8Array, stream = false, chunkSize?: number) => decodeReadonlyModelPreflightResponse(
  response(raw, stream, chunkSize), stream ? sseProfile : jsonProfile, new AbortController().signal);

test('143 independent completed JSON fixture yields exact text and raw hash, never fabricated usage', async () => {
  const raw = JSON.stringify(completed());
  assert.deepEqual(await decode(raw), { text: finalText, responseHash: createHash('sha256').update(raw).digest('hex') });
  await assert.rejects(decode(JSON.stringify({ ...completed(), usage: { input_tokens: 2, output_tokens: 3, total_tokens: 5 } })));
});

test('144 independent SSE fixture survives every byte boundary, CRLF, multi-data and comments', async () => {
  const raw = sse();
  for (const size of [1, 2, 3, 7, 97, 4096]) assert.equal((await decode(raw, true, size)).text, finalText);
  const multiline = raw.replaceAll('data: {"type":', 'data: {\ndata: "type":').replaceAll('\n', '\r\n');
  assert.equal((await decode(': local comment\n\n\n' + multiline + ': trailer\n\n', true, 1)).text, finalText);
});

test('142 status failures never retry or follow redirects and iterator is closed', async () => {
  for (const status of [301, 302, 307, 308, 401, 403, 429, 500, 503]) {
    let next = 0; let closed = 0;
    const value: PreflightHttpResponse = { status, headers: [['Location', 'https://other.invalid'], ['Retry-After', '1']],
      body: { [Symbol.asyncIterator]() { return { next: async () => { next++; return { done: true, value: undefined }; }, return: async () => { closed++; return { done: true, value: undefined }; } }; } } };
    await assert.rejects(decodeReadonlyModelPreflightResponse(value, jsonProfile, new AbortController().signal), { code: `READONLY_MODEL_PREFLIGHT_HTTP_${status}` });
    assert.equal(next, 0); assert.equal(closed, 1);
  }
});

test('142 duplicate, mismatched, compressed, injected, unknown headers and absent body are rejected', async () => {
  for (const headers of [
    [], [['Content-Type', 'application/json'], ['content-type', 'application/json']],
    [['Content-Type', 'text/event-stream']], [['Content-Type', 'application/json; charset=latin1']],
    [['Content-Type', 'application/json'], ['Content-Encoding', 'gzip']],
    [['Content-Type', 'application/json\r\nInjected: yes']], [['Content-Type', 'application/json'], ['Set-Cookie', 'synthetic']],
  ] as [string, string][][]) {
    const value = response(JSON.stringify(completed())); value.headers = headers;
    await assert.rejects(decodeReadonlyModelPreflightResponse(value, jsonProfile, new AbortController().signal));
  }
  const value = response(JSON.stringify(completed())); value.body = undefined as never;
  await assert.rejects(decodeReadonlyModelPreflightResponse(value, jsonProfile, new AbortController().signal));
  const identity = response(JSON.stringify(completed())); identity.headers.push(['Content-Encoding', 'identity']);
  assert.equal((await decodeReadonlyModelPreflightResponse(identity, jsonProfile, new AbortController().signal)).text, finalText);
});

test('143 malformed JSON, decoded duplicate keys, invalid UTF8 and unpaired Unicode are rejected', async () => {
  const raw = JSON.stringify(completed());
  for (const invalid of [raw.slice(0, -1), raw.replace('"status":"completed"', '"status":"completed","statu\\u0073":"completed"'),
    raw.replace('가나다', '\\ud800'), Buffer.concat([Buffer.from(raw), Buffer.from([0xc3])]), '\ufeff' + raw]) await assert.rejects(decode(invalid));
});

test('143 unsupported response states, fields, tools, refusal, multiple outputs and invalid identity fail closed', async () => {
  const mutations: ((value: ReturnType<typeof completed>) => void)[] = [
    (v) => { v.status = 'incomplete'; }, (v) => { v.model = 'another-model'; }, (v) => { v.id = 'unknown'; },
    (v) => { v.output.push(item()); }, (v) => { v.output[0]!.type = 'function_call'; },
    (v) => { v.output[0]!.content[0]!.type = 'refusal'; }, (v) => { v.output[0]!.id = 'wrong'; },
    (v) => { v.output[0]!.role = 'tool'; }, (v) => { Object.assign(v, { extra: true }); },
  ];
  for (const mutate of mutations) { const value = completed(); mutate(value); await assert.rejects(decode(JSON.stringify(value))); }
  await assert.rejects(decode(JSON.stringify({ ...completed(), usage: { input_tokens: 1, output_tokens: 2, total_tokens: 4 } })));
});

test('144 event/type, sequence, IDs, indexes, order and accumulated text are bound', async () => {
  const mutations: ((v: Record<string, unknown>[]) => void)[] = [
    (v) => { v[2]!.sequence_number = 3; }, (v) => { v[2]!.response_id = 'resp_other'; }, (v) => { v[2]!.item_id = 'msg_other'; },
    (v) => { v[2]!.content_index = 1; }, (v) => { v[2]!.output_index = 1; },
    (v) => { v[3]!.text = 'different'; }, (v) => { v[4]!.item = item('different'); }, (v) => { v[5]!.response = completed('different'); },
    (v) => { v[5]!.response = { ...completed(), id: 'resp_other' }; }, (v) => { v[2]!.type = 'response.function_call_arguments.delta'; },
    (v) => { v.splice(2, 1); }, (v) => { v.reverse(); }, (v) => { v[0]!.extra = true; },
  ];
  for (const mutate of mutations) { const value = events(); mutate(value); await assert.rejects(decode(sse(value), true)); }
  await assert.rejects(decode(sse().replace('event: response.created', 'event: response.completed'), true));
});

test('144 missing/duplicate terminal, post-terminal data, DONE, NDJSON and truncated SSE fail', async () => {
  for (const raw of [sse(events().slice(0, -1)), sse() + sse([events()[5]!]), sse() + 'data: [DONE]\n\n',
    sse().slice(0, -1), sse().replaceAll('\n\n', '\n'), events().map((event) => JSON.stringify(event)).join('\n') + '\n',
    'id: resume\n\n' + sse(), 'retry: 1\n\n' + sse(), sse().replace('event: response.created', 'event: response.created\nevent: response.created')]) {
    await assert.rejects(decode(raw, true));
  }
});

test('143/144 final text and raw SSE comments are checked for sensitive patterns without retaining raw errors', async () => {
  const secret = [['xo', 'xb'].join(''), '123456789012', '123456789012', 'abcdefghijklmnopqrstuvwx'].join('-');
  for (const raw of [sse(JSON.parse(JSON.stringify(events()).replace('가나다', secret))), `: ${secret}\n\n` + sse()]) {
    await assert.rejects(decode(raw, true), (error: unknown) => {
      assert.doesNotMatch(String(error), new RegExp(secret)); return true;
    });
  }
});

test('145 response body permits exact limit and rejects one byte above across chunks', async () => {
  const raw = JSON.stringify(completed());
  const exact = raw + ' '.repeat(PREFLIGHT_HTTP_LIMITS.responseBytes - Buffer.byteLength(raw));
  assert.equal((await decode(exact)).text, finalText);
  await assert.rejects(decode(exact + ' '), { code: 'READONLY_MODEL_PREFLIGHT_RESPONSE_LIMIT' });
});

test('145 final text byte limit accounts for Unicode and permits exact boundary', async () => {
  const text = '가'.repeat(5461) + 'a';
  assert.equal(Buffer.byteLength(text), 16 * 1024);
  assert.equal((await decode(JSON.stringify(completed(text)))).text, text);
  await assert.rejects(decode(JSON.stringify(completed(text + 'b'))), { code: 'READONLY_MODEL_PREFLIGHT_OUTPUT_LIMIT' });
});

test('145 SSE frame and total frame count include comments and empty frames', async () => {
  const comment = ':' + 'a'.repeat(64 * 1024 - 3) + '\n\n';
  assert.equal((await decode(comment + sse(), true)).text, finalText);
  await assert.rejects(decode(':' + 'a'.repeat(64 * 1024 - 2) + '\n\n' + sse(), true), { code: 'READONLY_MODEL_PREFLIGHT_FRAME_LIMIT' });
  assert.equal((await decode('\n'.repeat(2048 - 6) + sse(), true)).text, finalText);
  await assert.rejects(decode('\n'.repeat(2049 - 6) + sse(), true), { code: 'READONLY_MODEL_PREFLIGHT_FRAME_LIMIT' });
});

test('145 header bytes and count are checked before MIME semantics', async () => {
  for (const [count, bytes, limit] of [[17, 0, true], [16, 0, false], [1, 8193, true], [1, 8192, false]] as const) {
    const value = response(JSON.stringify(completed()));
    value.headers = bytes ? [['A', 'a'.repeat(bytes - 5)]] : Array.from({ length: count }, (_, i) => [`X-${i}`, 'a']);
    await assert.rejects(decodeReadonlyModelPreflightResponse(value, jsonProfile, new AbortController().signal), {
      code: limit ? 'READONLY_MODEL_PREFLIGHT_HEADER_LIMIT' : 'READONLY_MODEL_PREFLIGHT_INVALID_RESPONSE',
    });
  }
});

test('146 timeout interrupts stalled next and awaits bounded iterator cleanup', async () => {
  let returned = 0;
  const value = response('');
  value.body = { [Symbol.asyncIterator]() { return { next: () => new Promise(() => {}), return: async () => { returned++; return { done: true, value: undefined }; } }; } };
  await assert.rejects(decodeReadonlyModelPreflightResponse(value, jsonProfile, new AbortController().signal, { workTimeoutMs: 10, cleanupTimeoutMs: 20 }), { code: 'READONLY_MODEL_PREFLIGHT_TIMEOUT' });
  assert.equal(returned, 1);
});

test('146 abort ignores late chunks and failed/hanging iterator cleanup is unsafe', async () => {
  for (const cleanup of ['done', 'never', 'reject', 'not-done', 'missing']) {
    const controller = new AbortController();
    const value = response('');
    value.body = { [Symbol.asyncIterator]() { return {
      next: () => new Promise<IteratorResult<Uint8Array>>((resolve) => { setTimeout(() => resolve({ done: false, value: Buffer.from(JSON.stringify(completed())) }), 30); }),
      ...(cleanup === 'missing' ? {} : { return: () => cleanup === 'never' ? new Promise<IteratorResult<Uint8Array>>(() => {})
        : cleanup === 'reject' ? Promise.reject(new Error('untrusted cleanup')) : Promise.resolve({ done: cleanup !== 'not-done', value: undefined } as IteratorResult<Uint8Array>) }),
    }; } };
    const pending = decodeReadonlyModelPreflightResponse(value, jsonProfile, controller.signal, { workTimeoutMs: 100, cleanupTimeoutMs: 10 });
    controller.abort();
    await assert.rejects(pending, { code: cleanup === 'done' ? 'READONLY_MODEL_PREFLIGHT_CANCELLED' : 'READONLY_MODEL_PREFLIGHT_LIFECYCLE_UNSAFE' });
  }
});

test('135/146 invalid modes/budgets and thrown transport errors are rejected without raw disclosure', async () => {
  await assert.rejects(decodeReadonlyModelPreflightResponse(response(''), 'live' as never, new AbortController().signal));
  await assert.rejects(decodeReadonlyModelPreflightResponse(response(''), jsonProfile, new AbortController().signal, { workTimeoutMs: 55_001 }));
  const value = response('');
  value.body = { async *[Symbol.asyncIterator]() { throw new Error('UNTRUSTED_RAW_RESPONSE'); yield Buffer.from(''); } };
  await assert.rejects(decodeReadonlyModelPreflightResponse(value, jsonProfile, new AbortController().signal), (error: unknown) => {
    assert.doesNotMatch(String(error), /UNTRUSTED_RAW_RESPONSE/); return true;
  });
});
